SELECT COUNT(DISTINCT r.recipe_id) FROM recipe r LEFT JOIN recipe_category rc ON r.recipe_id = rc.recipe_id LEFT JOIN category c ON f.category_id = c.category_id WHERE r.status = 'ACTIVE'
AND REPLACE(c.category_name, ' ', '') = REPLACE(#{category}, ' ', '')
AND CAST(REPLACE(r.cooking_time, '분', '') AS UNSIGNED) <= #{maxCookTime}


SELECT DISTINCT r.*, f.food_name FROM recipe_view r
JOIN food f ON f.food_id = r.food_id
WHERE r.title LIKE #{pattern} OR f.food_name LIKE #{pattern}

mapper.update:
UPDATE recipe
SET
    title = #{title},
    food_id = #{foodId},
    cooking_time = #{cookingTime}

        , thumbnail = #{thumbnail}

WHERE recipe_id = #{recipeId}

UPDATE recipe
SET view_count = view_count + 1
WHERE recipe_id = #{recipeId}
